export function getWildcardPatternValidationError(pattern: string, packageName: string): string {
  const trimmedPattern = pattern.trim()

  // At least 2 non-* characters
  const nonAsteriskCount = trimmedPattern.replace(/\*/g, '').length
  if (nonAsteriskCount < 2) return 'Pattern must contain at least 2 non-* characters'

  // Only one * allowed
  const asteriskCount = (trimmedPattern.match(/\*/g) || []).length
  if (asteriskCount > 1) return 'Pattern can only contain one * character'

  // Pattern must address the packageName
  try {
    const regexPattern = trimmedPattern.replace(/\*/g, '.*')
    const regex = new RegExp(`^${regexPattern}$`)

    if (!regex.test(packageName)) {
      return `Pattern must match the package name "${packageName}"`
    }
  } catch {
    return 'Invalid regex pattern'
  }

  return ''
}
