import {ShieldCheckIcon} from '@primer/octicons-react'
import {AlertResolution, type AlertEvent} from '../../../types/alerts'
import {TimelineEventWithActor, getEventComment, EventComment} from './shared'

interface ClosedEventProps {
  event: AlertEvent
  alertResolution: AlertResolution
  closureReason?: string
}

function getClosedActionText(closureReason: string | undefined, resolution: AlertResolution): string {
  if (closureReason) {
    return `closed as ${closureReason}`
  }

  if (resolution === AlertResolution.Outdated) {
    return 'closed as outdated'
  }
  if (resolution === AlertResolution.ExceptionAdded || resolution === AlertResolution.LicensesAdded) {
    return 'closed as amendment'
  }
  return 'closed this alert'
}

export function ClosedEvent({event, alertResolution, closureReason}: ClosedEventProps) {
  const comment = getEventComment(event.eventBody)

  return (
    <TimelineEventWithActor
      event={event}
      icon={<ShieldCheckIcon size={16} />}
      badgeVariant="done"
      actionText={getClosedActionText(closureReason, alertResolution)}
      data-testid="timeline-event-closed"
    >
      {comment && <EventComment comment={comment} />}
    </TimelineEventWithActor>
  )
}
