export const AlertStatus = {
  Open: 'ALERT_STATUS_OPEN',
  ReviewRequested: 'ALERT_STATUS_REVIEW_REQUESTED',
  Closed: 'ALERT_STATUS_CLOSED',
  ReviewDenied: 'ALERT_STATUS_REVIEW_DENIED',
  ReviewExpired: 'ALERT_STATUS_REVIEW_EXPIRED',
} as const

export type AlertStatus = (typeof AlertStatus)[keyof typeof AlertStatus]

export const AlertResolution = {
  Unknown: 'unknown',
  ExceptionAdded: 'exception_added',
  Outdated: 'outdated',
  LicensesAdded: 'licenses_added',
} as const

export type AlertResolution = (typeof AlertResolution)[keyof typeof AlertResolution]

export const AlertEventType = {
  Opened: 'opened', // Synthetic event created by Rails
  AppearedInBranch: 'appeared_in_branch', // Synthetic event for branch info
  ReviewRequested: 'review_requested',
  ReviewDenied: 'review_denied',
  ReviewApproved: 'review_approved',
  ReviewExpired: 'review_expired',
  ExceptionAdded: 'exception_added',
  LicensesAdded: 'licenses_added',
  Closed: 'closed',
} as const

export type AlertEventType = (typeof AlertEventType)[keyof typeof AlertEventType]

// Event body types matching Go structs (snake_case as sent from Go service)
export type ExceptionAddedEventBody = {
  package_manager: string // Snake case from Go JSON
  package_name: string // Snake case from Go JSON
  level: string
  comment: string
}

export type LicensesAddedEventBody = {
  licenses: string[]
  level: string
  comment: string
}

export type ReviewEventBody = {
  comment?: string
  closure_reason?: string // Reason for requesting closure (e.g. "used in tests")
  pull_request_number?: number // PR number if review is related to a PR
  pull_request_title?: string // PR title for display
}

export type OpenedEventBody = {
  package_name: string
  package_version: string
  license: string
}

export type AppearedInBranchEventBody = {
  branch_name?: string
  pull_request_number?: number
  pull_request_title?: string
}

export type AlertEvent = {
  id: number | string // Can be numeric ID or synthetic string like "opened-123"
  alertId: number
  type: AlertEventType
  userId: number
  occurredAt: string // ISO 8601 timestamp from Rails
  eventBody: string // JSON string with event-specific data (comments, metadata)

  // Actor object enriched by Rails controller (NOT fetched client-side)
  actor?: {
    login: string
    avatarUrl: string
    url: string
  }
}

export type Alert = {
  createdAtIso: string
  number: number
  manifestName: string
  packageEcosystem: string
  packageName: string
  packageVersion: string
  license: string
  status: AlertStatus
  resolution: AlertResolution
  closureReason?: string
  link?: string
  branchName?: string
  events?: AlertEvent[] // Timeline events included with alert data
  externalPackageManagerUrl?: string
  packageRepositoryUrl?: string
}
