import {useAddLicensesForAlertMutation, useCreatePackageExceptionMutation} from '../../hooks/use-alert-update-mutation'

interface UseReviewerOnlyWorkflowMutationsProps {
  owner: string
  repo: string
  alertNumber: string
  onError: (error: string) => void
  onSettled: () => void
}

export const useReviewerOnlyWorkflowMutations = ({
  owner,
  repo,
  alertNumber,
  onError,
  onSettled,
}: UseReviewerOnlyWorkflowMutationsProps) => {
  const mutationCommonProps = {
    owner,
    repo,
    number: alertNumber,
    onError,
    onSettled,
  }

  const createExceptionMutation = useCreatePackageExceptionMutation(mutationCommonProps)
  const addLicensesForAlertMutation = useAddLicensesForAlertMutation(mutationCommonProps)

  const isLoading = createExceptionMutation.isPending || addLicensesForAlertMutation.isPending

  return {
    createExceptionMutation,
    addLicensesForAlertMutation,
    isLoading,
  }
}
