import {CheckIcon} from '@primer/octicons-react'
import type {AlertEvent} from '../../../types/alerts'
import {TimelineEventWithActor, getEventComment, EventComment} from './shared'

interface ReviewApprovedEventProps {
  event: AlertEvent
}

export function ReviewApprovedEvent({event}: ReviewApprovedEventProps) {
  const comment = getEventComment(event.eventBody)

  return (
    <TimelineEventWithActor
      event={event}
      icon={<CheckIcon size={16} />}
      actionText="approved closure request"
      data-testid="timeline-event-review-approved"
    >
      {comment && <EventComment comment={comment} />}
    </TimelineEventWithActor>
  )
}
