import {Timeline} from '@primer/react'
import {TimelineEventItem} from './TimelineEventItem'
import {AlertEventType, type AlertEvent, type AlertResolution} from '../../types/alerts'

interface AlertTimelineProps {
  events: AlertEvent[]
  alertResolution: AlertResolution
  closureReason?: string
  onReviewRequest?: () => void
  repoLicensePolicyPath?: string
  repoName?: string
}

export function AlertTimeline({
  events,
  alertResolution,
  closureReason,
  onReviewRequest,
  repoLicensePolicyPath,
  repoName,
}: AlertTimelineProps) {
  if (!events || events.length === 0) {
    return null
  }

  // Find the latest review_requested event (last one in the array)
  // Only this event should show the review button
  const latestReviewRequestedEventId = onReviewRequest
    ? events.findLast(event => event.type === AlertEventType.ReviewRequested)?.id
    : undefined

  const isLastEventClosed = events.at(-1)?.type === AlertEventType.Closed

  return (
    <Timeline clipSidebar={isLastEventClosed ? 'end' : undefined} data-testid="alert-timeline">
      {events.map(event => (
        <TimelineEventItem
          key={event.id}
          event={event}
          alertResolution={alertResolution}
          closureReason={closureReason}
          onReviewRequest={event.id === latestReviewRequestedEventId ? onReviewRequest : undefined}
          repoLicensePolicyPath={repoLicensePolicyPath}
          repoName={repoName}
        />
      ))}
    </Timeline>
  )
}
