import {Timeline, RelativeTime, Label, Stack, Link} from '@primer/react'
import type {TimelineBadgeVariant} from '@primer/react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {GitPullRequestIcon, NoteIcon} from '@primer/octicons-react'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import type {AlertEvent} from '../../../types/alerts'
import styles from './shared.module.css'

export interface BaseEventProps {
  event: AlertEvent
  icon: React.ReactNode
  actionText: React.ReactNode
  badgeVariant?: TimelineBadgeVariant
  'data-testid'?: string
}

/**
 * Shared wrapper for timeline events with actor (avatar, username)
 */
export function TimelineEventWithActor({
  event,
  icon,
  actionText,
  badgeVariant,
  children,
  'data-testid': dataTestId,
}: BaseEventProps & {children?: React.ReactNode}) {
  // Check if the actor is a bot by looking for [bot] suffix in login
  const isBot = event.actor?.login?.endsWith('[bot]')
  const displayLogin = isBot ? event.actor?.login?.replace(/\[bot\]$/i, '') : event.actor?.login
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  const hovercardAttrs = !isBot && event.actor ? getHovercardAttributesForType('user', {login: event.actor.login}) : {}

  return (
    <Timeline.Item data-testid={dataTestId}>
      <Timeline.Badge variant={badgeVariant}>{icon}</Timeline.Badge>
      <Timeline.Body>
        <Stack direction="horizontal" align="center" gap="none">
          {event.actor && (
            <>
              {isBot ? (
                <>
                  <GitHubAvatar src={event.actor.avatarUrl} size={20} alt="" />
                  <strong className="ml-1">{displayLogin}</strong>
                  <Label variant="secondary" className="ml-1">
                    bot
                  </Label>
                </>
              ) : event.actor.url ? (
                <Link href={event.actor.url} className={styles.actorLink} {...hovercardAttrs}>
                  <GitHubAvatar src={event.actor.avatarUrl} size={20} alt="" />
                  {displayLogin}
                </Link>
              ) : (
                <>
                  <GitHubAvatar src={event.actor.avatarUrl} size={20} alt="" />
                  <strong className="ml-1">{displayLogin}</strong>
                </>
              )}
            </>
          )}
          <span className="color-fg-muted ml-1">{actionText}</span>
          <RelativeTime datetime={event.occurredAt} className="ml-1" />
        </Stack>
        {children}
      </Timeline.Body>
    </Timeline.Item>
  )
}

/**
 * Shared wrapper for timeline events without actor (e.g., appeared_in_branch)
 */
export function TimelineEventWithoutActor({
  event,
  icon,
  actionText,
  badgeVariant,
  children,
  belowContent,
  'data-testid': dataTestId,
}: BaseEventProps & {children?: React.ReactNode; belowContent?: React.ReactNode}) {
  return (
    <Timeline.Item data-testid={dataTestId}>
      <Timeline.Badge variant={badgeVariant}>{icon}</Timeline.Badge>
      <Timeline.Body>
        <Stack direction="horizontal" align="center" gap="condensed">
          <span className="color-fg-muted">{actionText}</span>
          {children}
          <RelativeTime datetime={event.occurredAt} />
        </Stack>
        {belowContent}
      </Timeline.Body>
    </Timeline.Item>
  )
}

/**
 * Parse event body JSON safely
 */
export function parseEventBody<T>(eventBody: string): T | null {
  try {
    const parsed = JSON.parse(eventBody || '{}')
    if (typeof parsed !== 'object' || Array.isArray(parsed)) {
      return null
    }
    return parsed as T
  } catch {
    return null
  }
}

/**
 * Extract comment from event body
 */
export function getEventComment(eventBody: string): string | null {
  try {
    const parsed = JSON.parse(eventBody || '{}')
    return parsed?.comment || null
  } catch {
    return null
  }
}

/**
 * Shared PR link for timeline events
 */
export function PullRequestLink({number, title}: {number: number; title: string}) {
  return (
    <Stack direction="horizontal" align="center" gap="condensed" className="mt-1">
      <GitPullRequestIcon size={16} className="color-fg-success" />
      <Link href={`../../pull/${number}`} className={`f6 ${styles.defaultColorLink}`}>
        {title} #{number}
      </Link>
    </Stack>
  )
}

/**
 * Shared comment display for timeline events
 */
export function EventComment({comment}: {comment: string}) {
  return (
    <Stack direction="horizontal" align="center" gap="condensed" className="mt-1">
      <NoteIcon size={16} className="fgColor-muted" />
      <span className="f6 color-fg-muted">{comment}</span>
    </Stack>
  )
}
