import {PackageAction, type PolicyLevel} from '../../types/policies'
import {AMENDMENT_PACKAGE, AMENDMENT_PACKAGE_WILDCARD} from './constants'

export type CreatePolicyExceptionArgs = {
  comment: string
  policyLevel: PolicyLevel
  packageAction: PackageAction
  pattern: string
  closureReason?: string
}

export type AddLicensesForAlertArgs = {
  comment: string
  policyLevel: PolicyLevel
  closureReason?: string
}

type SubmitPolicyUpdateArgs = {
  comment: string
  closureReason?: string
  amendment: string
  scope: PolicyLevel
  wildcardPattern: string
  onCreatePolicyException: (args: CreatePolicyExceptionArgs) => void
  onAddLicensesForAlert: (args: AddLicensesForAlertArgs) => void
}

export function submitPolicyUpdate({
  comment,
  closureReason,
  amendment,
  scope,
  wildcardPattern,
  onCreatePolicyException,
  onAddLicensesForAlert,
}: SubmitPolicyUpdateArgs) {
  if (amendment === AMENDMENT_PACKAGE || amendment === AMENDMENT_PACKAGE_WILDCARD) {
    onCreatePolicyException({
      comment,
      policyLevel: scope,
      packageAction: amendment === AMENDMENT_PACKAGE ? PackageAction.Allowed : PackageAction.Private,
      pattern: amendment === AMENDMENT_PACKAGE ? '' : wildcardPattern,
      closureReason,
    })

    return
  }

  onAddLicensesForAlert({comment, policyLevel: scope, closureReason})
}
