import {Breadcrumbs, Heading, Stack} from '@primer/react'

import {AlertPageHeaderDetails} from './AlertPageHeaderDetails'
import type {AlertPageHeaderProps} from './types'

export const AlertPageHeader = ({
  title,
  alertNumber,
  backButtonText,
  backButtonUrl,
  buttonGroup,
  ...detailsProps
}: AlertPageHeaderProps) => (
  <Stack gap="condensed">
    <Stack direction="horizontal" gap="spacious" justify="space-between">
      <Stack gap="condensed">
        {backButtonText && <CrumbTrail label={backButtonText} href={backButtonUrl} />}

        <Heading as="h1" className="h2 lh-condensed mb-1 text-normal text-wrap-balance">
          <span>{title}</span> <span className="fgColor-muted">#{alertNumber}</span>
        </Heading>
      </Stack>

      {buttonGroup ? (
        <Stack direction="horizontal" gap="condensed">
          {buttonGroup}
        </Stack>
      ) : null}
    </Stack>

    <AlertPageHeaderDetails {...detailsProps} />
  </Stack>
)

type CrumbTrailProps = {
  label: string
  href?: string
}

const CrumbTrail = ({label, href}: CrumbTrailProps) => (
  <Breadcrumbs>
    {href ? (
      <Breadcrumbs.Item href={href}>
        <span>←</span> <span>{label}</span>
      </Breadcrumbs.Item>
    ) : (
      <Breadcrumbs.Item as="span" selected>
        {label}
      </Breadcrumbs.Item>
    )}
  </Breadcrumbs>
)
